const request = require('supertest');
const app = require('./app');

describe('GET /users', () => {
  it('should return all users by default', async () => {
    const res = await request(app).get('/users');
    expect(res.statusCode).toEqual(200);
    expect(res.body.status).toBe('success');
    expect(res.body.data.users).toHaveLength(4);
  });

  it('should respect limit parameter', async () => {
    const res = await request(app).get('/users?limit=2');
    expect(res.statusCode).toEqual(200);
    expect(res.body.data.users).toHaveLength(2);
  });

  it('should validate limit parameter', async () => {
    // Test invalid limit (too high)
    let res = await request(app).get('/users?limit=101');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toBe('fail');

    // Test invalid limit (negative)
    res = await request(app).get('/users?limit=-1');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toBe('fail');

    // Test invalid limit (not a number)
    res = await request(app).get('/users?limit=abc');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toBe('fail');
  });

  it('should validate sort parameter', async () => {
    // Test invalid sort field
    const res = await request(app).get('/users?sort=invalid');
    expect(res.statusCode).toEqual(400);
    expect(res.body.status).toBe('fail');

    // Test valid sort fields
    const validSorts = ['id', 'name', 'email'];
    for (const sort of validSorts) {
      const res = await request(app).get(`/users?sort=${sort}`);
      expect(res.statusCode).toEqual(200);
      expect(res.body.status).toBe('success');
    }
  });

  it('should return sorted results', async () => {
    const res = await request(app).get('/users?sort=name&limit=2');
    expect(res.statusCode).toEqual(200);
    expect(res.body.data.users[0].name).toBe('Alice'); // First alphabetically
    expect(res.body.data.users[1].name).toBe('Bob');  // Second alphabetically
  });
});

describe('GET /health', () => {
  it('should return server health status', async () => {
    const res = await request(app).get('/health');
    expect(res.statusCode).toEqual(200);
    expect(res.body.status).toBe('success');
    expect(res.body).toHaveProperty('timestamp');
  });
});

describe('Error Handling', () => {
  it('should handle 404 for unknown routes', async () => {
    const res = await request(app).get('/unknown-route');
    expect(res.statusCode).toEqual(404);
    expect(res.body.status).toBe('fail');
  });
});

