const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize user input against XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset, search } = req.query;

    // Input validation and sanitization
    const parsedLimit = parseInt(limit) || 10;
    const parsedOffset = parseInt(offset) || 0;

    // Ensure limits are within reasonable bounds
    const safeLimit = Math.min(Math.max(parsedLimit, 1), 100); // Between 1 and 100
    const safeOffset = Math.max(parsedOffset, 0); // Non-negative

    // Sample data - in real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      // Sanitize search input to prevent injection
      const sanitizedSearch = xss(search.trim());
      if (sanitizedSearch.length > 0 && sanitizedSearch.length < 50) {
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
          user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
        );
      }
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(safeOffset, safeOffset + safeLimit);

    res.json({
      success: true,
      count: paginatedUsers.length,
      total: filteredUsers.length,
      data: paginatedUsers
    });
  } catch (error) {
    // Log the error for debugging (in production, use proper logging)
    console.error('Error in /users endpoint:', error);

    // Send generic error message to client
    res.status(500).json({
      success: false,
      message: 'An error occurred while processing your request'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: 'Route not found'
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Prepare error response
  const errorResponse = {
    success: false,
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : err.message || 'Internal server error'
  };

  // Include error details in development only
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.error = err;
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json(errorResponse);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

