// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { body, validationResult } = require('express-validator');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(xss()); // Sanitize against XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', 
  // Query parameter validation
  [
    // Validate and sanitize query parameters
    body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    body('offset').optional().isInt({ min: 0 }).toInt(),
    body('sort').optional().isIn(['id', 'name', 'email'])
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      // Sample user data (in a real app, this would come from a database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply query parameters if provided
      let filteredUsers = [...users];

      // Sort users if sort parameter is provided and valid
      if (req.query.sort) {
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1;
          if (a[req.query.sort] > b[req.query.sort]) return 1;
          return 0;
        });
      }

      // Apply pagination if limit and offset are provided
      if (req.query.limit !== undefined || req.query.offset !== undefined) {
        const limit = parseInt(req.query.limit) || 10;
        const offset = parseInt(req.query.offset) || 0;
        filteredUsers = filteredUsers.slice(offset, offset + limit);
      }

      res.json({
        count: filteredUsers.length,
        users: filteredUsers
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// POST endpoint example with comprehensive validation
app.post('/users',
  [
    // Validate and sanitize input
    body('name').trim().isLength({ min: 2, max: 50 }).escape().withMessage('Name must be between 2 and 50 characters'),
    body('email').trim().isEmail().normalizeEmail().withMessage('Please provide a valid email address'),
    body('age').optional().isInt({ min: 0, max: 150 }).withMessage('Age must be a number between 0 and 150')
  ],
  (req, res) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      // In a real application, you would save the user to a database here
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        ...req.body
      };

      res.status(201).json({
        message: 'User created successfully',
        user: newUser
      });
    } catch (error) {
      console.error('Error in POST /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        message: process.env.NODE_ENV === 'development' ? error.message : undefined
      });
    }
  }
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Set default status code
  const statusCode = err.status || 500;

  // Determine if we should show error details (only in development)
  const showErrorDetails = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : 'Bad request',
    message: showErrorDetails ? err.message : undefined,
    // Include stack trace only in development
    ...(showErrorDetails && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  // Close server & exit process
  server.close(() => process.exit(1));
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Close server & exit process
  server.close(() => process.exit(1));
});

module.exports = app;

