/**
 * Test suite for the Express.js application
 * Demonstrates testing of validation, error handling, and security features
 */

const request = require('supertest');
const app = require('./app');

describe('Express App Security Features', () => {
  let server;

  beforeAll(() => {
    // Create a separate server instance for testing
    server = app.listen(0);
  });

  afterAll(() => {
    server.close();
  });

  describe('Health Endpoint', () => {
    test('should return 200 and status ok', async () => {
      const response = await request(server).get('/health');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });
  });

  describe('Input Validation', () => {
    test('should validate user creation data', async () => {
      // Valid data
      const validUser = {
        name: 'John Doe',
        email: 'john@example.com',
        age: 30
      };

      const response = await request(server)
        .post('/users')
        .send(validUser)
        .expect('Content-Type', /json/)
        .expect(201);

      expect(response.body).toHaveProperty('message', 'User created successfully');
      expect(response.body.user).toHaveProperty('name', 'John Doe');
    });

    test('should reject invalid name', async () => {
      const invalidUser = {
        name: 'J', // Too short
        email: 'john@example.com'
      };

      const response = await request(server)
        .post('/users')
        .send(invalidUser)
        .expect('Content-Type', /json/)
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
      expect(response.body.details).toBeInstanceOf(Array);
      expect(response.body.details[0]).toHaveProperty('msg', expect.stringContaining('Name must be between'));
    });

    test('should reject invalid email', async () => {
      const invalidUser = {
        name: 'John Doe',
        email: 'invalid-email'
      };

      const response = await request(server)
        .post('/users')
        .send(invalidUser)
        .expect('Content-Type', /json/)
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
      expect(response.body.details[0]).toHaveProperty('msg', expect.stringContaining('valid email'));
    });
  });

  describe('Rate Limiting', () => {
    test('should apply rate limiting', async () => {
      // Make multiple requests quickly
      const promises = [];
      for (let i = 0; i < 5; i++) {
        promises.push(request(server).get('/health'));
      }

      const responses = await Promise.all(promises);
      // All should succeed since we're well under the limit
      responses.forEach(response => {
        expect(response.status).toBe(200);
      });
    });
  });

  describe('Error Handling', () => {
    test('should handle 404 for undefined routes', async () => {
      const response = await request(server)
        .get('/undefined-route')
        .expect(404);

      expect(response.body).toHaveProperty('error', 'Not found');
      expect(response.body.message).toContain('Route');
    });

    test('should handle validation errors properly', async () => {
      const response = await request(server)
        .post('/users')
        .send({}) // Empty body
        .expect(400);

      expect(response.body).toHaveProperty('error', 'Validation failed');
      expect(response.body.details.length).toBeGreaterThan(0);
    });
  });

  describe('Security Headers', () => {
    test('should return security headers', async () => {
      const response = await request(server).get('/health');

      // Check for common security headers set by helmet
      expect(response.headers).toHaveProperty('x-content-type-options');
      expect(response.headers).toHaveProperty('x-frame-options');
      expect(response.headers).toHaveProperty('x-xss-protection');
    });
  });
});

