// Secure Express application with proper error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json()); // Parse JSON bodies
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const { detailed } = req.query;

    // Input validation
    if (detailed !== undefined && typeof detailed !== 'string') {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Query parameter "detailed" must be a string'
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
    };

    // Only include additional info if explicitly requested and validated
    if (detailed === 'true') {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  } catch (error) {
    // Centralized error handling
    console.error('Health check error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, sort } = req.query;

    // Parse and validate limit
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Parse and validate offset
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative integer'
        });
      }
    }

    // Validate sort parameter
    const validSortOptions = ['name', 'email', 'id', '-name', '-email', '-id'];
    let parsedSort = 'id'; // default
    if (sort !== undefined) {
      if (typeof sort !== 'string' || !validSortOptions.includes(sort)) {
        return res.status(400).json({
          error: 'Bad Request',
          message: `Sort must be one of: ${validSortOptions.join(', ')}`
        });
      }
      parsedSort = sort;
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (parsedSort.startsWith('-')) {
        const field = parsedSort.substring(1);
        return b[field] > a[field] ? 1 : -1;
      } else {
        return a[parsedSort] > b[parsedSort] ? 1 : -1;
      }
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      count: paginatedUsers.length,
      total: users.length,
      limit: parsedLimit,
      offset: parsedOffset,
      users: paginatedUsers
    });
  } catch (error) {
    // Centralized error handling
    console.error('Users endpoint error:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred while processing your request'
    });
  }
});

// 404 handler - should be placed after all route definitions
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.originalUrl} not found`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak stack trace in production
  const statusCode = error.status || 500;
  const message = error.message || 'Internal Server Error';

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : 'Bad Request',
    message: process.env.NODE_ENV === 'development' ? message : 
             (statusCode === 500 ? 'An unexpected error occurred' : message),
    // Only include stack in development
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server }; // Export both for testing flexibility

