// Improved application with better error handling and input validation
// Following security best practices

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload

// Data sanitization against NoSQL injection
app.use(mongoSanitize());

// Data sanitization against XSS
app.use(xss());

// Prevent parameter pollution
app.use(hpp());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes'
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any were expected
    const { timestamp } = req.query;

    // If we expected timestamp validation, we could do it here
    // For now, just return a healthy response
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      status: 'error',
      message: 'Internal server error during health check'
    });
  }
});

// Users endpoint with proper error handling and validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Input validation
    const validatedLimit = limit 
      ? Math.min(parseInt(limit) || 10, 100) // Max 100 records
      : 10;

    const validatedOffset = offset 
      ? Math.max(parseInt(offset) || 0, 0) 
      : 0;

    // Sanitize search input (additional protection beyond xss-clean)
    const validatedSearch = search 
      ? typeof search === 'string' 
        ? search.trim().substring(0, 100) // Limit length
        : '' 
      : '';

    // Mock database query with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (validatedSearch) {
      const searchLower = validatedSearch.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers
      .slice(validatedOffset, validatedOffset + validatedLimit);

    res.json({
      status: 'success',
      data: paginatedUsers,
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        total: filteredUsers.length,
        returnCount: paginatedUsers.length
      }
    });

  } catch (error) {
    // Log error for debugging (in production, use proper logging library)
    console.error('Error in /users endpoint:', error);

    // Don't expose internal error details to client
    res.status(500).json({
      status: 'error',
      message: 'Unable to retrieve users at this time'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Global error handler:', error);

  // In production, you might want to hide error details
  const statusCode = error.status || 500;
  res.status(statusCode).json({
    status: 'error',
    message: statusCode === 500 
      ? 'Internal server error' 
      : error.message || 'An unexpected error occurred',
    // Only include error details in development
    ...(process.env.NODE_ENV === 'development' && { stack: error.stack })
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

