// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { validationResult, body, param, query } = require('express-validator');
const logger = require('./logger'); // Assuming you have a logger setup

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS if needed
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging middleware for security monitoring
app.use((req, res, next) => {
  logger.info(`Incoming ${req.method} request to ${req.path}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// Health check endpoint with validation
app.get('/health', 
  [
    // Validate query parameters if any
    query('detailed').optional().isBoolean().withMessage('Detailed parameter must be boolean')
  ],
  (req, res) => {
    // Handle validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array()
      });
    }

    const detailed = req.query.detailed === 'true';
    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    if (detailed) {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  }
);

// Users endpoint with proper validation and error handling
app.get('/users', 
  [
    // Validate query parameters
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('sort').optional().isIn(['id', 'name', 'email']).withMessage('Sort field must be id, name, or email'),
    query('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc')
  ],
  (req, res) => {
    // Handle validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation failed for /users endpoint', {
        errors: errors.array(),
        ip: req.ip
      });
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array()
      });
    }

    try {
      // Sample data - in real app this would come from database
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      // Apply filtering, sorting, pagination based on validated params
      let filteredUsers = [...users];

      // Apply limit and offset
      const limit = parseInt(req.query.limit) || filteredUsers.length;
      const offset = parseInt(req.query.offset) || 0;

      // Apply sorting
      if (req.query.sort) {
        const reverse = req.query.order === 'desc' ? -1 : 1;
        filteredUsers.sort((a, b) => {
          if (a[req.query.sort] < b[req.query.sort]) return -1 * reverse;
          if (a[req.query.sort] > b[req.query.sort]) return 1 * reverse;
          return 0;
        });
      }

      // Apply pagination
      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      logger.info('Users retrieved successfully', {
        count: paginatedUsers.length,
        ip: req.ip,
        params: req.query
      });

      res.json({
        status: 'success',
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length
        }
      });
    } catch (error) {
      logger.error('Error retrieving users', {
        error: error.message,
        stack: error.stack,
        ip: req.ip
      });
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// POST endpoint example with comprehensive validation
app.post('/users',
  [
    // Validate and sanitize input
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name can only contain letters, spaces, hyphens, and apostrophes'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Please provide a valid email address')
      .normalizeEmail(), // Standardizes email addresses

    body('age')
      .optional()
      .isInt({ min: 0, max: 150 }).withMessage('Age must be between 0 and 150')
  ],
  async (req, res) => {
    // Handle validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation failed for POST /users', {
        errors: errors.array(),
        ip: req.ip,
        body: req.body // Be careful with logging sensitive data in production
      });
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array()
      });
    }

    try {
      // In a real application, you would save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        name: req.body.name,
        email: req.body.email,
        age: req.body.age
      };

      logger.info('User created successfully', {
        userId: newUser.id,
        ip: req.ip
      });

      res.status(201).json({
        status: 'success',
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      logger.error('Error creating user', {
        error: error.message,
        stack: error.stack,
        ip: req.ip
      });
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// Parameter validation example
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Invalid user ID provided', {
        errors: errors.array(),
        ip: req.ip,
        params: req.params
      });
      return res.status(400).json({
        status: 'error',
        message: 'Validation failed',
        errors: errors.array()
      });
    }

    try {
      const userId = parseInt(req.params.id);

      // Simulate database lookup
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' }
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        logger.info('User not found', {
          userId,
          ip: req.ip
        });
        return res.status(404).json({
          status: 'error',
          message: 'User not found'
        });
      }

      logger.info('User retrieved successfully', {
        userId,
        ip: req.ip
      });

      res.json({
        status: 'success',
        data: user
      });
    } catch (error) {
      logger.error('Error retrieving user', {
        error: error.message,
        stack: error.stack,
        ip: req.ip,
        userId: req.params.id
      });
      res.status(500).json({
        status: 'error',
        message: 'Internal server error'
      });
    }
  }
);

// 404 handler - should be placed after all route definitions
app.use('*', (req, res) => {
  logger.warn('404 Not Found', {
    path: req.path,
    method: req.method,
    ip: req.ip
  });
  res.status(404).json({
    status: 'error',
    message: 'Route not found'
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log the error for debugging/security monitoring
  logger.error('Unhandled error occurred', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine error status code
  const statusCode = err.status || 500;

  // Don't leak sensitive information in production
  const message = process.env.NODE_ENV === 'development' 
    ? err.message 
    : statusCode === 500 
      ? 'Internal server error' 
      : err.message;

  res.status(statusCode).json({
    status: 'error',
    message: message,
    // Only include error details in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', { promise, reason: reason.message || reason });
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception thrown', { error: error.message, stack: error.stack });
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

module.exports = app;

// Simple logging utility for security monitoring
const winston = require('winston');

// Define log format
const logFormat = winston.format.printf(({ level, message, timestamp, ...meta }) => {
  const metaStr = Object.keys(meta).length ? JSON.stringify(meta) : '';
  return `${timestamp} [${level.toUpperCase()}]: ${message} ${metaStr}`;
});

// Create logger instance
const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss.SSS' }),
    winston.format.errors({ stack: true }),
    winston.format.splat(),
    logFormat
  ),
  transports: [
    // Console transport for all environments
    new winston.transports.Console(),

    // File transport for errors
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    }),

    // File transport for all logs
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880, // 5MB
      maxFiles: 5
    })
  ]
});

// If we're not in production, also log to the console with colors
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

module.exports = logger;

