  describe('POST /users', () => {
    it('should create a user with valid data', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'john@example.com',
          age: 30
        });

      expect(res.statusCode).toEqual(201);
      expect(res.body.status).toEqual('success');
      expect(res.body.data).toHaveProperty('name', 'John Doe');
    });

    it('should reject invalid name', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'J', // Too short
          email: 'john@example.com'
        });

      expect(res.statusCode).toEqual(400);
      expect(res.body.status).toEqual('error');
    });

    it('should reject invalid email', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: 'John Doe',
          email: 'invalid-email'
        });

      expect(res.statusCode).toEqual(400);
      expect(res.body.status).toEqual('error');
    });

    it('should reject malicious input (XSS attempt)', async () => {
      const res = await request(app)
        .post('/users')
        .send({
          name: '<script>alert("xss")</script>',
          email: 'john@example.com'
        });

      // Should either sanitize or reject the input
      expect(res.statusCode).toEqual(400); // Validation should catch this
    });
  });

  // Test parameter validation
  describe('GET /users/:id', () => {
    it('should return a user with valid ID', async () => {
      const res = await request(app).get('/users/1');
      expect(res.statusCode).toEqual(200);
      expect(res.body.status).toEqual('success');
      expect(res.body.data).toHaveProperty('id', 1);
    });

    it('should reject invalid user ID', async () => {
      const res = await request(app).get('/users/invalid');
      expect(res.statusCode).toEqual(400);
      expect(res.body.status).toEqual('error');
    });

    it('should return 404 for non-existent user', async () => {
      const res = await request(app).get('/users/999');
      expect(res.statusCode).toEqual(404);
      expect(res.body.status).toEqual('error');
    });
  });

  // Test 404 handling
  describe('404 Handling', () => {
    it('should return 404 for unknown routes', async () => {
      const res = await request(app).get('/unknown-route');
      expect(res.statusCode).toEqual(404);
      expect(res.body.status).toEqual('error');
    });
  });
});

