// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { validate, Joi } = require('express-validation');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const logger = require('./logger');

// Initialize express app
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize user input to prevent XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} - ${req.ip}`);
  next();
});

// Validation schemas
const healthCheckValidation = {
  query: Joi.object({
    // Optional query parameters for health check
    detailed: Joi.boolean().optional(),
    timeout: Joi.number().integer().min(1).max(30).optional()
  })
};

const usersValidation = {
  query: Joi.object({
    // Query parameters for users endpoint
    limit: Joi.number().integer().min(1).max(100).optional(),
    offset: Joi.number().integer().min(0).optional(),
    search: Joi.string().max(50).optional(),
    sort: Joi.string().valid('name', 'email', 'id').optional()
  })
};

// Health check endpoint with validation
app.get('/health', validate(healthCheckValidation), (req, res, next) => {
  try {
    const { detailed, timeout } = req.query;

    // Basic health response
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      service: 'user-service'
    };

    // Add detailed info if requested
    if (detailed) {
      healthData.uptime = process.uptime();
      healthData.memoryUsage = process.memoryUsage();
    }

    res.status(200).json(healthData);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Users endpoint with validation
app.get('/users', validate(usersValidation), (req, res, next) => {
  try {
    const { limit = 10, offset = 0, search, sort } = req.query;

    // Mock user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (search) {
      const searchLower = search.toLowerCase();
      filteredUsers = users.filter(user =>
        user.name.toLowerCase().includes(searchLower) ||
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply sorting if provided
    if (sort) {
      filteredUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.status(200).json({
      count: paginatedUsers.length,
      total: filteredUsers.length,
      offset,
      limit,
      users: paginatedUsers
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  // Log the error for monitoring
  logger.error({
    message: error.message,
    stack: error.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Handle validation errors from express-validation
  if (error.isJoi) {
    return res.status(400).json({
      error: 'Validation Error',
      details: error.details.map(detail => ({
        field: detail.context.key,
        message: detail.message
      })),
      timestamp: new Date().toISOString()
    });
  }

  // Handle express-validation errors
  if (error.status) {
    return res.status(error.status).json({
      error: error.message || 'Validation Error',
      // Include validation details if available
      ...(error.details && { details: error.details }),
      timestamp: new Date().toISOString()
    });
  }

  // Handle operational errors (known errors)
  if (error.isOperational) {
    return res.status(error.statusCode || 500).json({
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }

  // Handle programming errors (unknown errors)
  // Don't leak stack trace in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : error.message;

  res.status(statusCode).json({
    error: message,
    // Only include stack in development
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack }),
    timestamp: new Date().toISOString()
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception thrown:', error);
  process.exit(1);
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Graceful shutdown
const shutdown = async () => {
  logger.info('Received shutdown signal, closing server...');
  server.close(async (err) => {
    if (err) {
      logger.error('Error during shutdown:', err);
      process.exit(1);
    }
    logger.info('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    logger.warn('Force closing connections after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = { app, server };

// Simple logger utility
const winston = require('winston');

// Define log format
const logFormat = winston.format.printf(({ level, message, timestamp, ...meta }) => {
  const metaStr = Object.keys(meta).length ? JSON.stringify(meta) : '';
  return `${timestamp} [${level}]: ${message} ${metaStr}`;
});

// Create logger instance
const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss.SSS' }),
    winston.format.errors({ stack: true }),
    winston.format.splat(),
    logFormat
  ),
  transports: [
    // Console transport
    new winston.transports.Console(),
    // File transport for errors
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    // File transport for all logs
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// If we're not in production, also log to console with colors
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

module.exports = logger;

