// Improved application with enhanced error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { celebrate, Joi, errors } = require('celebrate');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', 
  celebrate({
    query: Joi.object({
      limit: Joi.number().integer().min(1).max(100).default(10),
      offset: Joi.number().integer().min(0).default(0),
      sort: Joi.string().valid('name', 'email', 'id').default('id'),
      order: Joi.string().valid('asc', 'desc').default('asc'),
      search: Joi.string().allow('').max(50)
    })
  }),
  (req, res) => {
    try {
      // In a real app, you would query a database here with the validated parameters
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Apply pagination and filtering based on validated query params
      const { limit, offset, search } = req.query;
      let filteredUsers = users;

      if (search) {
        const lowerSearch = search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(lowerSearch) || 
          user.email.toLowerCase().includes(lowerSearch)
        );
      }

      const paginatedUsers = filteredUsers.slice(offset, offset + limit);

      res.json({
        data: paginatedUsers,
        pagination: {
          limit,
          offset,
          total: filteredUsers.length,
          hasMore: offset + limit < filteredUsers.length
        }
      });
    } catch (error) {
      console.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error' 
      });
    }
  }
);

// Example POST endpoint with validation
app.post('/users', 
  celebrate({
    body: Joi.object({
      name: Joi.string().min(2).max(50).required(),
      email: Joi.string().email().required(),
      age: Joi.number().integer().min(0).max(150).optional()
    })
  }),
  (req, res) => {
    try {
      // In a real app, you would save to database here
      const newUser = {
        id: Date.now(), // Simple ID generation for demo
        ...req.body
      };

      res.status(201).json({
        message: 'User created successfully',
        data: newUser
      });
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ 
        error: 'Failed to create user' 
      });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error(`[${new Date().toISOString()}] Error:`, err);

  // Handle celebration validation errors
  if (err.isJoi) {
    return res.status(400).json({
      error: 'Validation failed',
      details: err.details.map(detail => detail.message)
    });
  }

  // Handle other known errors
  if (err.status) {
    return res.status(err.status).json({
      error: err.message || 'Error occurred'
    });
  }

  // Handle unexpected errors
  // In production, don't leak stack traces or internal details
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: 'Internal server error',
    // Only include message in non-production environments
    ...(!isProduction && { message: err.message })
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception thrown:', error);
  // Graceful shutdown logic here
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

