// Improved application with proper error handling, input validation, and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS with default options (configure as needed)
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize user input from XSS
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Health check endpoint with input validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any are expected
    const { timestamp } = req.query;

    // If timestamp param is provided, validate it
    if (timestamp && isNaN(Date.parse(timestamp))) {
      return res.status(400).json({
        error: 'Invalid timestamp format'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    // Handle unexpected errors
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// Users endpoint with proper error handling and validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Limit must be a number between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Offset must be a non-negative number'
        });
      }
    }

    // Validate search parameter (if provided)
    let sanitizedSearch = '';
    if (search !== undefined) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({
          error: 'Search must be a string with maximum 50 characters'
        });
      }
      // Basic sanitization (in addition to xss-clean middleware)
      sanitizedSearch = search.trim();
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Filter users based on search if provided
    let filteredUsers = users;
    if (sanitizedSearch) {
      const searchLower = sanitizedSearch.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchLower) || 
        user.email.toLowerCase().includes(searchLower)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / parsedLimit)
      }
    });

  } catch (error) {
    // Log the error for internal debugging (in production, use proper logger)
    console.error('Error in /users endpoint:', error);

    // Send generic error message to client
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  // Log error for internal debugging
  console.error('Global error handler:', error);

  // Determine status code
  const statusCode = error.status || 500;

  // Send appropriate error response
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error' 
      : error.message || 'Internal server error'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

